import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.ChIlRNAd.js";const u=JSON.parse('{"title":"Jobs & Queue (BullMQ)","description":"","frontmatter":{},"headers":[],"relativePath":"en/technical/jobs.md","filePath":"en/technical/jobs.md"}'),s={name:"en/technical/jobs.md"};function i(r,e,c,n,l,h){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="jobs-queue-bullmq" tabindex="-1">Jobs &amp; Queue (BullMQ) <a class="header-anchor" href="#jobs-queue-bullmq" aria-label="Permalink to &quot;Jobs &amp; Queue (BullMQ)&quot;">​</a></h1><h2 id="why-bullmq" tabindex="-1">Why BullMQ <a class="header-anchor" href="#why-bullmq" aria-label="Permalink to &quot;Why BullMQ&quot;">​</a></h2><p>Gmail operations (bulk actions, archiving thousands of emails) can take several minutes. A synchronous HTTP request would inevitably time out.</p><p>BullMQ allows:</p><ul><li>Enqueuing the job → immediate <code>202 Accepted</code> response with a <code>jobId</code></li><li>Asynchronous execution in a worker</li><li>Progress tracking over SSE</li><li>Automatic retry on error (exponential backoff, 3 attempts)</li><li>Cancelling a job as long as it has not started</li></ul><hr><h2 id="job-types" tabindex="-1">Job Types <a class="header-anchor" href="#job-types" aria-label="Permalink to &quot;Job Types&quot;">​</a></h2><p><code>JobType</code> (<code>backend/src/jobs/queue.ts</code>). Every type is processed by the <strong>unified worker</strong> (<code>jobs/workers/unified.worker.ts</code>), which dispatches on <code>job.name</code>:</p><table tabindex="0"><thead><tr><th>Type</th><th>Enqueued by</th></tr></thead><tbody><tr><td><code>bulk_operation</code></td><td><code>POST /api/gmail/:accountId/messages/bulk</code> (ids or Gmail query); <code>POST /api/unsubscribe/:accountId/newsletters/:senderEmail/delete</code>; <code>runRule()</code> for Gmail actions</td></tr><tr><td><code>archive_mails</code></td><td><code>POST /api/archive/:accountId/archive</code>; <code>runRule()</code> for the <code>archive_nas</code> action; scheduler (automatic NAS backup); the worker itself (follow-up of a capped backup)</td></tr><tr><td><code>run_rule</code></td><td><code>POST /api/rules/:accountId/:ruleId/run</code>; scheduler (scheduled rules)</td></tr><tr><td><code>scan_unsubscribe</code></td><td><code>POST /api/unsubscribe/:accountId/scan</code></td></tr><tr><td><code>integrity_check</code></td><td><code>POST /api/integrity/check/async</code> (admin); scheduler (daily, 3 AM)</td></tr><tr><td><code>encrypt_archives</code></td><td><code>POST /api/privacy/:accountId/encryption/encrypt</code></td></tr><tr><td><code>import_mbox</code></td><td><code>POST /api/import/:accountId/mbox</code></td></tr><tr><td><code>import_imap</code></td><td><code>POST /api/import/:accountId/imap</code></td></tr><tr><td><code>purge_archive_trash</code></td><td>scheduler (daily, 4 AM)</td></tr><tr><td><code>backfill_body_text</code></td><td>scheduler, once at startup if some archives still lack <code>body_text</code></td></tr><tr><td><code>apply_retention</code></td><td>No caller at the moment: <code>POST /api/retention/run</code> applies the policies synchronously</td></tr></tbody></table><p><code>POST /api/jobs/:jobId/retry</code> can re-enqueue any type (see <a href="#retry">Retry</a>).</p><hr><h2 id="queue-configuration" tabindex="-1">Queue Configuration <a class="header-anchor" href="#queue-configuration" aria-label="Permalink to &quot;Queue Configuration&quot;">​</a></h2><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Shared &quot;nid&quot; queue</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">defaultJobOptions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  attempts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,                                   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 3 attempts on failure</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  backoff</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;exponential&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">delay</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 2s, 4s, 8s</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  removeOnComplete</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Keep the last 100 completed jobs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  removeOnFail</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },                   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Keep the last 50 failed jobs</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>enqueueJob(type, payload, opts)</code> takes two options:</p><ul><li><code>dedupId</code>: while a job with this id is waiting or running, enqueueing it again is a no-op (scheduled rules, backups, backfill).</li><li><code>delay</code> (ms): the job stays <code>scheduled</code> (BullMQ <code>delayed</code>) until then and can still be cancelled.</li></ul><p>Credentials in the payload (<code>passphrase</code>, <code>imapConfig.pass</code>) are stripped from the copy stored in the database; in Redis, such jobs are removed as soon as they end.</p><hr><h2 id="concurrency" tabindex="-1">Concurrency <a class="header-anchor" href="#concurrency" aria-label="Permalink to &quot;Concurrency&quot;">​</a></h2><p>The unified worker runs with a concurrency of <strong>3</strong> (at most 3 simultaneous jobs), shared by all types. Gmail calls are additionally limited per account (<code>gmail/gmail-throttle.ts</code>).</p><hr><h2 id="database-tracking" tabindex="-1">Database Tracking <a class="header-anchor" href="#database-tracking" aria-label="Permalink to &quot;Database Tracking&quot;">​</a></h2><p>Each job is tracked in the <code>jobs</code> table (PostgreSQL) for:</p><ul><li>Persistence after restart (BullMQ Redis may be flushed)</li><li>History access even after <code>removeOnComplete</code></li><li>Display in the frontend without a direct Redis dependency</li></ul><h3 id="pre-insertion" tabindex="-1">Pre-insertion <a class="header-anchor" href="#pre-insertion" aria-label="Permalink to &quot;Pre-insertion&quot;">​</a></h3><p><code>enqueueJob()</code> immediately inserts a row in <code>jobs</code> (<code>status: &#39;pending&#39;</code>, or <code>&#39;scheduled&#39;</code> with <code>delay</code>), unless BullMQ deduplicated the job. The frontend (SSE) therefore finds the job right away.</p><p>Handlers then perform an <code>UPDATE</code> (not an <code>INSERT</code>) to move the job to <code>active</code>, then <code>completed</code> or <code>failed</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pending   → active → completed</span></span>
<span class="line"><span>scheduled ↗        → failed</span></span>
<span class="line"><span>pending / scheduled → cancelled (manual cancellation; 409 once active)</span></span></code></pre></div><p><code>GET /api/jobs</code> lists the user&#39;s jobs over the last 30 days (filters: comma-separated <code>status</code>, <code>accountId</code>, <code>limit</code>; <code>withCounts=true</code> adds per-status counts for the Activity page).</p><hr><h2 id="undo-window" tabindex="-1">Undo Window <a class="header-anchor" href="#undo-window" aria-label="Permalink to &quot;Undo Window&quot;">​</a></h2><p>Destructive actions are enqueued with <code>delay = delayMs</code> (request body, <strong>10 s by default</strong>, 0 to 60 s):</p><ul><li><code>POST /api/gmail/:accountId/messages/bulk</code></li><li><code>POST /api/unsubscribe/:accountId/newsletters/:senderEmail/delete</code></li><li><code>POST /api/rules/:accountId/:ruleId/run</code></li></ul><p>The response contains the BullMQ <code>jobId</code> and <code>runAt</code>. During that delay, <code>DELETE /api/jobs/:jobId</code> (BullMQ id or row id) removes the job from the queue and marks the row <code>cancelled</code>. A job that is already <code>active</code> cannot be stopped: the route answers <strong>409</strong>. On the frontend, <code>UndoToast</code> shows the countdown.</p><hr><h2 id="retry" tabindex="-1">Retry <a class="header-anchor" href="#retry" aria-label="Permalink to &quot;Retry&quot;">​</a></h2><p><code>POST /api/jobs/:jobId/retry</code> re-enqueues the stored payload under a new id (<code>retryOf</code> = original row id) and answers <code>202 { jobId, retryOf }</code>. Types whose credentials are not stored (<code>import_imap</code>, <code>encrypt_archives</code>) are refused with <strong>409</strong>: start them again from their page.</p><p>Capped bulk actions (<code>BULK_QUERY_MAX</code>, 50,000 by default) do not restart on their own: a notification offers to retry. Capped NAS backups, on the other hand, chain a differential follow-up after <code>ARCHIVE_CONTINUE_DELAY_MIN</code> minutes (15 by default), at most <code>ARCHIVE_CHAIN_MAX</code> times (20).</p><hr><h2 id="real-time-tracking-sse" tabindex="-1">Real-Time Tracking (SSE) <a class="header-anchor" href="#real-time-tracking-sse" aria-label="Permalink to &quot;Real-Time Tracking (SSE)&quot;">​</a></h2><h3 id="per-job-get-api-jobs-jobid-events" tabindex="-1">Per job: <code>GET /api/jobs/:jobId/events</code> <a class="header-anchor" href="#per-job-get-api-jobs-jobid-events" aria-label="Permalink to &quot;Per job: \`GET /api/jobs/:jobId/events\`&quot;">​</a></h3><ul><li><code>:jobId</code> = BullMQ id or row id; the job must belong to the user (404 otherwise)</li><li>Sends the current <code>jobs</code> row on connect; if the job is already finished, sends the final state then <code>event: close</code></li><li>The broadcaster (<code>startQueueEventBroadcaster</code>) listens to BullMQ <code>QueueEvents</code> (<code>progress</code>, <code>completed</code>, <code>failed</code>) and re-reads the <code>jobs</code> row (by <code>bullmq_id</code>) before broadcasting <code>{ status, progress, processed, total }</code></li><li>Heartbeat every 15 s</li><li>Frontend: <code>useJobSSE(jobId)</code> (reconnects with backoff), rendered by <code>JobProgressInline</code></li></ul><h3 id="per-user-get-api-events" tabindex="-1">Per user: <code>GET /api/events</code> <a class="header-anchor" href="#per-user-get-api-events" aria-label="Permalink to &quot;Per user: \`GET /api/events\`&quot;">​</a></h3><p>Stream of the signed-in user, through one Redis pub/sub channel per user (<code>events/events.service.ts</code>):</p><ul><li><code>counters</code> on connect and on every change: <code>{ mails, activeRules, activeJobs }</code></li><li><code>job</code> when a job starts or finishes (published by the worker)</li><li>Heartbeat every 30 s</li><li>Frontend: <code>useLiveCounters()</code> (navigation badges)</li></ul><p>End-of-job toasts come from <code>useGlobalJobNotifier</code> (polls active jobs every 5 s), and in-app notifications from <code>notify()</code> in the worker.</p><hr><h2 id="scheduler" tabindex="-1">Scheduler <a class="header-anchor" href="#scheduler" aria-label="Permalink to &quot;Scheduler&quot;">​</a></h2><p><code>startRuleScheduler()</code> (<code>jobs/scheduler.ts</code>) runs every <strong>60 seconds</strong> inside the API process:</p><table tabindex="0"><thead><tr><th>Task</th><th>Frequency</th><th>Mode</th></tr></thead><tbody><tr><td><code>integrity_check</code></td><td>Daily (3 AM tick)</td><td>Job</td></tr><tr><td><code>purge_archive_trash</code></td><td>Daily (4 AM tick)</td><td>Job</td></tr><tr><td>Automatic NAS backup (differential <code>archive_mails</code>)</td><td>Per <code>mail_accounts.backup_interval</code> (1h / 6h / 24h), active accounts with <code>backup_enabled</code> and no <code>auth_error_at</code></td><td>Job, <code>dedupId: backup-&lt;accountId&gt;</code></td></tr><tr><td>Scheduled rules (<code>run_rule</code>)</td><td><code>hourly</code>, <code>daily</code>, <code>weekly</code>, <code>monthly</code> based on <code>rules.last_run_at</code></td><td>Job, <code>dedupId: run_rule-&lt;ruleId&gt;</code></td></tr><tr><td><code>backfill_body_text</code></td><td>Once at startup, if archives remain to fill</td><td>Job</td></tr><tr><td>Inbox Zero snapshots</td><td>Every 6 h</td><td>In-process</td></tr><tr><td>Gmail label sync (<code>syncAllLabels()</code>)</td><td>Daily (first tick after startup)</td><td>In-process — see <a href="./api/labels.html">API — Labels</a></td></tr><tr><td>Expired emails (<code>processExpiredEmails()</code>)</td><td>Every 15 min</td><td>In-process</td></tr><tr><td>Expired share links (<code>cleanupExpiredShares()</code>)</td><td>Hourly</td><td>In-process</td></tr></tbody></table><p><code>startReportScheduler()</code> (<code>reports/report.scheduler.ts</code>) checks hourly and, on Mondays, generates each user&#39;s weekly report as a notification.</p><h3 id="archive-trash-purge" tabindex="-1">Archive Trash Purge <a class="header-anchor" href="#archive-trash-purge" aria-label="Permalink to &quot;Archive Trash Purge&quot;">​</a></h3><p>The <code>purge_archive_trash</code> job:</p><ol><li>Reads configuration from the <code>system_config</code> table (<code>archive_trash_retention_days</code>, <code>archive_trash_purge_enabled</code>)</li><li>If disabled (<code>purge_enabled = false</code>), the job ends without action</li><li>Finds archived emails where <code>deleted_at &lt; now - retention_days</code></li><li>Deletes the associated files (EML + attachments) from storage</li><li>Deletes the database entries</li></ol><p>The default retention is <strong>30 days</strong>. An admin can change it (<code>PUT /api/archive/config/trash</code>), or it can be edited directly in the <code>system_config</code> table.</p>`,54)])])}const b=t(s,[["render",i]]);export{u as __pageData,b as default};
